"use strict";

// Development-only packaging. The website uses the resulting local files offline.
const fs = require("node:fs/promises");
const path = require("node:path");
const crypto = require("node:crypto");
const root = path.resolve(__dirname, "..");
const fontSources = {
    body: "https://raw.githubusercontent.com/notofonts/noto-fonts/main/hinted/ttf/NotoSans/NotoSans-Regular.ttf",
    heading:
        "https://raw.githubusercontent.com/google/fonts/main/ofl/patrickhand/PatrickHand-Regular.ttf",
    devanagari:
        "https://raw.githubusercontent.com/notofonts/noto-fonts/main/hinted/ttf/NotoSansDevanagari/NotoSansDevanagari-Regular.ttf",
    symbols:
        "https://raw.githubusercontent.com/notofonts/noto-fonts/main/hinted/ttf/NotoSansSymbols2/NotoSansSymbols2-Regular.ttf",
    emoji: "https://raw.githubusercontent.com/google/fonts/main/ofl/notoemoji/NotoEmoji%5Bwght%5D.ttf",
};

async function download(url) {
    const response = await fetch(url, { signal: AbortSignal.timeout(30000) });
    if (!response.ok) throw new Error(`Could not download ${url}: ${response.status}`);
    return Buffer.from(await response.arrayBuffer());
}

async function prepare() {
    const vendor = path.join(root, "public", "assets", "vendor");
    const licenses = path.join(root, "licenses", "pdf-export");
    await fs.mkdir(vendor, { recursive: true });
    await fs.mkdir(licenses, { recursive: true });
    for (const [source, name] of [
        ["pdf-lib/dist/pdf-lib.min.js", "pdf-lib.min.js"],
        ["@pdf-lib/fontkit/dist/fontkit.umd.min.js", "fontkit.umd.min.js"],
        ["regenerator-runtime/runtime.js", "regenerator-runtime.js"],
    ]) {
        const script = await fs.readFile(require.resolve(source), "utf8");
        await fs.writeFile(
            path.join(vendor, name),
            script.replace(/\/\/# sourceMappingURL=.*$/gm, ""),
        );
    }
    await fs.copyFile(
        require.resolve("pdf-lib/LICENSE.md"),
        path.join(licenses, "pdf-lib-LICENSE.md"),
    );
    await fs.copyFile(
        require.resolve("regenerator-runtime/LICENSE"),
        path.join(licenses, "regenerator-LICENSE.txt"),
    );
    const fonts = {},
        sources = {};
    for (const [name, url] of Object.entries(fontSources)) {
        const bytes = await download(url);
        fonts[name] = bytes.toString("base64");
        sources[name] = { url, sha256: crypto.createHash("sha256").update(bytes).digest("hex") };
    }
    const script = `/* Generated by scripts/prepare-pdf-assets.js. Font licenses: licenses/pdf-export/. */\n(function(root){ const fonts = ${JSON.stringify(fonts)}; if(typeof module === "object" && module.exports) module.exports = fonts; else root.PlanmatePdfFonts = fonts; })(typeof window === "object" ? window : globalThis);\n`;
    await fs.writeFile(path.join(root, "public", "assets", "pdf-fonts.js"), script);
    await fs.writeFile(
        path.join(licenses, "font-sources.json"),
        JSON.stringify(sources, null, 4) + "\n",
    );
    for (const [url, name] of [
        ["https://raw.githubusercontent.com/notofonts/noto-fonts/main/LICENSE", "Noto-OFL.txt"],
        [
            "https://raw.githubusercontent.com/google/fonts/main/ofl/patrickhand/OFL.txt",
            "PatrickHand-OFL.txt",
        ],
        [
            "https://raw.githubusercontent.com/google/fonts/main/ofl/notoemoji/OFL.txt",
            "NotoEmoji-OFL.txt",
        ],
    ])
        await fs.writeFile(path.join(licenses, name), await download(url));
    console.log("Local PDF libraries and fonts are ready.");
}
prepare().catch((error) => {
    console.error(error.message);
    process.exitCode = 1;
});
